int readAverageAdc(int pin, int samples) {
  long sum = 0;
  for (int i = 0; i < samples; i++) sum += analogRead(pin);
  return sum / samples;
}

codeExamples.code:
int readAverageAdc(int pin, int samples) {
  long sum = 0;
  for (int i = 0; i < samples; i++) {
    sum += analogRead(pin);
    delay(2);
  }
  return (int)(sum / samples);
}
void setup() { Serial.begin(9600); }
void loop() {
  Serial.println(readAverageAdc(A0, 10));
  delay(300);
}

